window.kbPageData["views/entry/k-83e53ed14ea92058"] = {"key":"entry/k-83e53ed14ea92058","state":{"route":"entry/k-83e53ed14ea92058"},"node":{"id":"k-83e53ed14ea92058","mode":"k","title":"严格贯彻执行民主集中制","type":"制度与规则","domain":"政治理论","reading":"","intro":"","priority":100,"aliases":[],"qs":[],"current":false,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":true,"tags":{"专题":["party"],"主类":["制度与规则"],"出处性质":["机构注释"],"学科":["政治理论"],"来源主题":["党政制度与理论"],"资料类别":["非时政"]},"directorySummary":"2.严格贯彻执行民主集中制\n《决定》从 4 个方面作出了具体部署。一是坚持和加强党中央集中统一领导。完善党\n中央集中统一领导的体制机制，完善党中央重大决策部署落实机制，严格执行向党中央请\n示报告制度，推进政治监督具体化、精准化、常态化。二是提高党内民主质量。坚持和完\n善党内民主制度，健全党内情况通报…","sources":[{"id":"c054b0f36623248e","label":"严格贯彻执行民主集中制","topic":"党政制度与理论","category":"非时政","text":"2.严格贯彻执行民主集中制\n《决定》从 4 个方面作出了具体部署。一是坚持和加强党中央集中统一领导。完善党\n中央集中统一领导的体制机制，完善党中央重大决策部署落实机制，严格执行向党中央请\n示报告制度，推进政治监督具体化、精准化、常态化。二是提高党内民主质量。坚持和完\n善党内民主制度，健全党内情况通报制度、情况反映制度，坚持党内民主平等的同志关系。\n三是严格执行领导班子决策议事规则。完善党委（党组）议事规则和决策程序，加强重大\n决策合规合法性审查，健全重大决策、重要人事任免、重大项目安排、大额资金使用事项\n监督机制，也就是常说的“三重一大”监督机制。四是规范“一把手”履职用权。落实加\n强对“一把手”和领导班子监督的制度规定，健全领导班子权力运行制约机制，完善同级\n监督制度机制。","source":{"doc":"41195a191a57c1c36332","first":15,"last":15,"page":15,"file":"《中国共产党第二十届中央委员会第五次全体会议公报》解读.pdf"},"basis":"机构注释"}]},"questions":{},"terms":{},"references":{},"topics":[{"slug":"party","title":"党的建设与自我革命"}],"units":{"k-83e53ed14ea92058":[]}};
